from construire import Chapter,fig,box,qs,sub
from figures_communes import common,plot
from math import sqrt,pi,atan2,cos,sin

def create():
 c=Chapter(4,'L’oscillateur harmonique','1.4 / oscillateur harmonique','les oscillations idéales d’une masse sur ressort et d’un circuit LC, avec conditions initiales, phase et bilan énergétique.')
 common(c)
 plot(c,'sinus',[('cos(deg(x))','$x/A$','otNavy'),('-sin(deg(x))',r'$v/(A\omega_0)$','otGreenDark')],xmax=12.57,xlabel=r'$\omega_0 t$',ylabel='Grandeurs réduites')
 plot(c,'energies',[('cos(deg(x))^2',r'$\mathcal E_p/\mathcal E$','otNavy'),('sin(deg(x))^2',r'$\mathcal E_c/\mathcal E$','otGreenDark')],xmax=6.283,ymin=0,ymax=1.12,xlabel=r'$\omega_0t$',ylabel='Énergie réduite')
 c.f('phase',r'''\draw[axis](-3,0)--(3.5,0)node[right]{$x/A$};\draw[axis](0,-2.7)--(0,3)node[above]{$v/(\omega_0A)$};\draw[otNavy,thick](0,0)circle(2.1);\draw[-{Stealth},otGreenDark,thick](2.1,0)arc(0:-60:2.1);\node[lab,text width=4.5cm,align=left]at(7,1){Parcours horaire :\\à $x=A$, l’accélération est négative.\\Le cercle traduit l’énergie constante.};''')
 c.intro="Une masse se déplace tandis qu’un ressort se déforme ; dans un circuit LC, le courant et la tension se relaient. Ces situations partagent la même équation. L’oscillateur harmonique sert de modèle de référence avant l’étude des pertes au chapitre 05."
 c.mapping="Établir et reconnaître l’équation harmonique ; la résoudre avec deux conditions initiales. Définir amplitude, phase, période, fréquence et pulsation. Comparer les réalisations mécanique et électrique et construire leur bilan énergétique."
 c.prereq=r"Dérivée seconde, fonctions sinus et cosinus ; énergie cinétique ; force de rappel linéaire $F_x=-kx$ ; relations de C et L. La loi $m\ddot x=\sum F_x$ est rappelée ici et sera développée en mécanique."
 c.method="Repérer l’équilibre, choisir l’écart à cet équilibre, écrire l’équation de mouvement puis les deux conditions initiales. Fixer les coefficients avant de convertir en amplitude et phase. Vérifier l’énergie."
 c.boundary="Page interne 15 (page PDF 52). La rubrique 1.4 est répartie entre chapitres 04, 05 et 06 ; les frottements puis le forçage sinusoïdal sont traités ensuite."
 c.diagnostic=qs(r"Dériver $x=A\cos(\omega t+\varphi)$ une puis deux fois.",r"Donner la relation entre $T$, $f$ et $\omega$.",r"Une équation $\ddot x+100x=0$ a quelle pulsation ? Quelle unité porte le coefficient 100 ?",r"Que vaut la force d’un ressort si l’écart à l’équilibre est positif ?",r"Écrire l’énergie cinétique et l’énergie potentielle élastique d’une masse m sur un ressort k.",r"Rappeler les énergies de C et L.",r"Un cosinus est-il déterminé par sa seule valeur à l’origine ?",r"Si $x(0)=A>0$ et $v(0)=0$, dans quel sens la vitesse évolue-t-elle juste après ?")
 c.diag_sol=sub('D1 à D3',r"$v=-A\omega\sin(\omega t+\varphi)$ et $\ddot x=-A\omega^2\cos(\omega t+\varphi)$. $f=1/T$ et $\omega=2\pi f$. La pulsation vaut $10$ rad/s ; le coefficient de x porte l’unité s$^{-2}$.")+sub('D4 à D6',r"Pour $x>0$, $F_x=-kx<0$. $\mathcal E_c=mv^2/2$, $\mathcal E_p=kx^2/2$ ; $\mathcal E_C=Cu^2/2$ et $\mathcal E_L=Li^2/2$.")+sub('D7 et D8',r"Il faut deux conditions indépendantes, par exemple x et v à une date. Pour $x(0)=A>0$, l’accélération initiale est négative : la vitesse devient négative juste après le départ.")
 c.c('Reconnaître le modèle harmonique',r'''Un système oscillant peut s’éloigner puis revenir autour d’un équilibre. Le modèle harmonique suppose une force de rappel proportionnelle à l’écart, ou une relation équivalente entre les variables d’un circuit, et aucune dissipation.
'''+box('loi','L’équation de référence',r"$\result{\ddot x+\omega_0^2x=0}$, avec $\omega_0>0$. L’accélération est opposée au déplacement. $\omega_0$ se mesure en rad/s et $\omega_0^2$ en s$^{-2}$.")+fig('sinus','La vitesse est en quadrature avec le déplacement ; les deux courbes partagent la même pulsation.')+sub('Pourquoi le mouvement ne s’arrête pas à l’équilibre',"La force s’annule à l’équilibre mais la vitesse y est maximale. La masse continue donc son mouvement ; l’inertie et le rappel transforment alternativement énergie cinétique et énergie potentielle.")+box('piege','Le signe du rappel est décisif',r"$\ddot x-\omega_0^2x=0$ décrit des exponentielles et un équilibre instable. Une erreur de signe ne constitue pas un simple décalage de phase."))
 c.c('Masse et ressort horizontal',r'''Une masse m se déplace sans frottement sur un support horizontal. Les forces verticales se compensent ; l’axe x mesure l’écart par rapport à l’équilibre du ressort. La force de rappel est $F_x=-kx$.
'''+fig('ressort','L’origine du déplacement est l’équilibre, pas nécessairement le point d’attache du ressort.')+box('loi','De la dynamique à l’oscillation',r"$m\ddot x=-kx$, donc $\omega_0=\sqrt{k/m}$, $T_0=2\pi\sqrt{m/k}$ et $f_0=1/T_0$.")+sub('Application',r"Avec $m=0{,}20$ kg et $k=20$ N/m, $\omega_0=10$ rad/s, $T_0=0{,}628$ s et $f_0=1{,}592$ Hz. Une masse plus grande ralentit le mouvement ; une raideur plus grande l’accélère.")+box('methode','Les hypothèses à annoncer',"Le ressort est utilisé dans son domaine linéaire ; sa masse est négligée ; le guidage assure un seul degré de liberté ; les frottements et les pertes sont négligés. Une amplitude excessive peut invalider le modèle."))
 c.c('Résoudre avec deux conditions initiales',box('loi','La forme la plus sûre pour commencer',r"$x(t)=a\cos(\omega_0t)+b\sin(\omega_0t)$. Si $x(0)=x_0$ et $v(0)=v_0$, alors $a=x_0$ et $b=v_0/\omega_0$ : $\result{x=x_0\cos(\omega_0t)+(v_0/\omega_0)\sin(\omega_0t)}$.")+sub('Démonstration',r"Chacun des deux termes satisfait l’équation. À l’origine, le sinus s’annule et le cosinus vaut un : $x(0)=a$. En dérivant, $v(0)=\omega_0b$. Les deux conditions fixent donc les deux constantes indépendantes.")+sub('Exemple avec lancement',r"$\omega_0=10$ rad/s, $x_0=3$ cm, $v_0=0{,}40$ m/s : $x=0{,}03\cos(10t)+0{,}04\sin(10t)$ en mètres. La vitesse initiale positive interdit de représenter le départ comme une simple libération depuis une position extrême.")+fig('sinus','Les deux fonctions sinus et cosinus forment une base pour toutes les conditions initiales.')+box('methode','Un triple contrôle',r"Évaluer x(0), puis v(0), puis $\ddot x+\omega_0^2x$. Ces trois vérifications évitent d’accepter une solution qui satisfait seulement l’équation."))
 c.c('Amplitude et phase sans ambiguïté',box('loi','Une autre écriture de la même solution',r"$x=A\cos(\omega_0t+\varphi)$ avec $A\geq0$. On a $A=\sqrt{x_0^2+(v_0/\omega_0)^2}$, $A\cos\varphi=x_0$ et $-A\omega_0\sin\varphi=v_0$. Pour $A>0$, $\varphi=\operatorname{atan2}(-v_0/\omega_0,x_0)$ à $2\pi$ près.")+sub('Pourquoi une tangente ne suffit pas',r"$\tan\varphi=-v_0/(\omega_0x_0)$ ne distingue pas des angles séparés de $\pi$. Le signe de x et celui de v fixent le quadrant. Si $A=0$, le système reste à l’équilibre et la phase est indéterminée.")+sub('Exemple du lancement',r"$x_0=0{,}03$ m et $v_0/\omega_0=0{,}04$ m donnent $A=0{,}05$ m et $\varphi=-0{,}9273$ rad. À l’origine, le cosinus vaut $0{,}6$ et le sinus $-0{,}8$ : la position et la vitesse sont correctement retrouvées.")+box('piege','La phase dépend de l’origine des temps',r"Changer l’origine temporelle modifie $\varphi$, mais ne change ni l’amplitude ni la période. Une différence de phase doit être définie entre grandeurs de même fréquence et dans une convention précise."))
 c.c('Période, fréquence et lecture d’un graphe',box('loi','Des grandeurs distinctes',r"$T_0=2\pi/\omega_0$ ; $f_0=1/T_0$ ; $\omega_0=2\pi f_0$. L’amplitude est le maximum de l’écart à l’équilibre. Pour $x=x_e+A\cos(\omega_0t+\varphi)$, elle vaut $(x_{\max}-x_{\min})/2$, et $x_e=(x_{\max}+x_{\min})/2$.")+fig('sinus','Entre deux maxima du même signal, il s’écoule une période ; entre un maximum et le minimum suivant, une demi-période.')+sub('Mesurer plusieurs cycles',r"Si N périodes occupent $t_b-t_a$, estimer $T=(t_b-t_a)/N$. Pour une même précision de datation des extrémités, augmenter N réduit l’incertitude relative. Ne pas compter un demi-cycle comme un cycle complet.")+sub('Isochronisme',"Dans le modèle harmonique, la période est indépendante de l’amplitude. Une variation nette de la période avec l’amplitude indique une limite du modèle, une perturbation ou une erreur de mesure. L’isochronisme ne signifie pas seulement que la pulsation est constante au cours d’une courbe donnée."))
 c.c('L’énergie d’un oscillateur mécanique',box('loi','Un échange sans dissipation',r"$\mathcal E=\tfrac12mv^2+\tfrac12kx^2=\tfrac12kA^2$. Sa dérivée vaut $v(m\ddot x+kx)=0$. L’énergie est constante ; $\mathcal E_c$ et $\mathcal E_p$ s’échangent périodiquement.")+fig('energies','L’énergie cinétique est maximale au passage par l’équilibre ; l’énergie potentielle aux positions extrêmes.')+sub('Deux conséquences utiles',r"À l’équilibre, $v_{\max}=\omega_0A$. À un déplacement x, $v^2=\omega_0^2(A^2-x^2)$. L’énergie donne le module de la vitesse ; son signe dépend du sens du mouvement.")+sub('Exemple',r"Pour $m=0{,}20$ kg, $k=20$ N/m et $A=5$ cm : $\mathcal E=25$ mJ et $v_{\max}=0{,}50$ m/s. Au point $x=3$ cm, $|v|=0{,}40$ m/s ; les deux signes correspondent aux deux passages par cette position."))
 c.c('Le circuit LC idéal',fig('lc','Le courant i entre par l’armature positive de C. Il circule ensuite dans L ; les deux tensions réceptrices se somment à zéro.')+box('loi','Équation électrique',r"$u_L+u_C=0$, $u_L=L\dot i$ et $i=C\dot u_C$. Donc $\ddot u_C+u_C/(LC)=0$ et $\omega_0=1/\sqrt{LC}$. En charge q, $\ddot q+q/(LC)=0$ avec $i=\dot q$.")+sub('Condition initiale usuelle',r"Pour $u_C(0)=U_0$ et $i(0)=0$, $u_C=U_0\cos(\omega_0t)$ et $i=-C\omega_0U_0\sin(\omega_0t)$. Le signe négatif traduit le fait que le condensateur se décharge d’abord dans le sens opposé au courant de référence.")+sub('Exemple',r"$L=100$ mH et $C=1\ \mathrm{\mu F}$ donnent $\omega_0=3162$ rad/s et $T_0=1{,}987$ ms. Avec $U_0=3$ V, le courant maximal en module vaut $U_0\sqrt{C/L}=9{,}49$ mA.")+box('piege','Un composant réel dissipe',"La résistance de la bobine, les connexions et les instruments amortissent une expérience réelle. Le LC idéal constitue une référence ; il n’annonce pas des oscillations indéfinies dans tout montage."))
 c.c('Énergie électrique et analogie',box('loi','Le bilan du LC',r"$\mathcal E=\tfrac12Li^2+\tfrac12Cu_C^2$. Sa dérivée vaut $i(L\dot i+u_C)=0$. En charge q, $\mathcal E=\tfrac12L\dot q^2+q^2/(2C)$.")+sub('Un dictionnaire utile',r'''\begin{tabularx}{\linewidth}{@{}Y Y@{}}\toprule
Mécanique & Électricité\\\midrule
Déplacement $x$ & Charge $q$\\
Vitesse $\dot x$ & Courant $i=\dot q$\\
Masse $m$ & Inductance $L$\\
Raideur $k$ & Inverse de capacité $1/C$\\
Énergie cinétique $m\dot x^2/2$ & Énergie magnétique $Li^2/2$\\
Énergie potentielle $kx^2/2$ & Énergie électrique $q^2/(2C)$\\\bottomrule
\end{tabularx}''')+fig('energies','Les mêmes courbes normalisées décrivent les deux réserves d’énergie du LC et du système masse-ressort.')+box('methode','Comparer les bonnes variables',r"L’analogie la plus directe porte sur x et q. Si l’on choisit u comme variable électrique, il faut aussi transformer les coefficients énergétiques : q = Cu."))
 c.c('Le portrait de phase',r'''Un portrait de phase trace la vitesse en fonction de la position, au fil du temps. Il représente les états successifs du système et non un trajet dans l’espace physique.
'''+box('loi','L’énergie définit une ellipse',r"$x^2/A^2+v^2/(\omega_0^2A^2)=1$. Les demi-axes sont A et $\omega_0A$. Dans les coordonnées réduites $(x/A,v/(\omega_0A))$, la courbe est un cercle.")+fig('phase','Le sens de parcours découle de la dynamique ; il ne se choisit pas arbitrairement.')+sub('Lire les états',r"Aux extrêmes de x, v = 0 ; aux passages par x = 0, $|v|$ est maximal. Au point $(A,0)$, l’accélération vaut $-\omega_0^2A$, donc la trajectoire descend. Une même ellipse représente toutes les phases pour la même énergie.")+box('piege','Les échelles des axes comptent',r"Un portrait dessiné avec deux unités différentes peut paraître circulaire sans que les demi-axes physiques soient égaux. Pour retrouver $\omega_0$, prendre le rapport $v_{\max}/A$ en unités SI."))
 c.c('Déplacer l’équilibre',r'''Une force constante $F_0$ agit sur la masse en plus du rappel : $m\ddot x=-kx+F_0$. Le mouvement n’est plus centré sur x = 0, mais reste harmonique autour d’un autre équilibre.
'''+box('loi','Translation de variable',r"$x_e=F_0/k$. Poser $X=x-x_e$ donne $\ddot X+\omega_0^2X=0$. La solution est $x=x_e+(x_0-x_e)\cos(\omega_0t)+(v_0/\omega_0)\sin(\omega_0t)$.")+sub('Ressort vertical',r"Avec l’axe vers le bas et l’allongement $z$ depuis la longueur à vide, $m\ddot z=mg-kz$. L’équilibre est $z_e=mg/k$. La pesanteur déplace l’équilibre mais ne modifie pas la pulsation dans ce modèle linéaire.")+sub('Échelon dans un LC série',r"Une source constante E impose $LC\ddot u_C+u_C=E$. Poser $U=u_C-E$. Avec $u_C(0)=0$ et $i(0)=0$, $u_C=E(1-\cos\omega_0t)$. Sans perte, la tension atteint 2E ; elle ne se stabilise pas à E.")+box('piege','Le permanent harmonique idéal',"Une excitation constante ne garantit pas une convergence si le système n’est pas amorti. La solution particulière fixe le centre d’oscillation ; le régime libre conserve son amplitude."))
 c.c('Déterminer un paramètre par oscillation',box('loi','Deux relations expérimentales',r"Masse-ressort : $T^2=(4\pi^2/k)m$ ; LC : $T^2=4\pi^2LC$. Une droite permet de tester le modèle et de limiter l’effet d’une seule lecture.")+sub('Une estimation de raideur',r"Mesurer plusieurs masses et plusieurs périodes. Ajuster $T^2=am+b$. Dans le modèle de ressort sans masse, $k=4\pi^2/a$ et b = 0. Une ordonnée non nulle peut suggérer une masse mobile supplémentaire ou un biais ; elle ne permet pas à elle seule d’en identifier la cause.")+sub('Incertitude sur une mesure isolée',r"Si $k=4\pi^2m/T^2$ et si m et T sont indépendants : $u(k)/k=\sqrt{[u(m)/m]^2+[2u(T)/T]^2}$. Le facteur 2 sur l’incertitude relative de période est essentiel.")+fig('ressort','Un modèle de masse ponctuelle doit inclure les accessoires qui se déplacent avec le chariot.')+box('methode','Ce que l’on teste',"Comparer la période à différentes amplitudes, suivre une éventuelle diminution d’amplitude et examiner les résidus de l’ajustement. Un faible amortissement peut laisser la période presque constante tout en révélant des pertes.") )
 c.tp_title='Mesurer une raideur par la période'
 c.tp=qs("Installer un chariot guidé horizontalement, relié à un ressort ; mesurer toute la masse mobile. Choisir une amplitude compatible avec le domaine linéaire.",r"Enregistrer x(t). Déterminer l’équilibre, l’amplitude et la durée de dix périodes si l’enregistrement le permet.",r"Recommencer avec plusieurs masses et ajuster $T^2=am+b$. En déduire k ; examiner b et les résidus.","Comparer deux amplitudes initiales. Discuter isochronisme et décroissance de l’amplitude.",r"Comparer $v_{\max}$ estimé par dérivation à $\omega_0A$, en expliquant la sensibilité au bruit.")+box('docu','Série simulée pour préparer le traitement',r"$m$ (kg) : $0{,}10$, $0{,}15$, $0{,}20$, $0{,}25$.\par $T$ (s) : $0{,}444$, $0{,}544$, $0{,}628$, $0{,}702$.\par Ces valeurs sont des résultats arrondis du modèle $k=20$ N/m, pas des mesures effectuées.")+box('methode','Attendu',"Schéma et hypothèses, chronométrage expliqué, ajustement avec unités, résultat et incertitude, limites physiques et discussion d’un éventuel amortissement.")
 c.num_title='Comparer une intégration à l’exact'
 c.num=r'''Euler appliqué naïvement à un oscillateur sans perte crée de l’énergie. Le code suivant permet de mesurer cette dérive, puis de la comparer à un schéma qui met à jour la vitesse avant la position.
\begin{verbatim}
import numpy as np
w, h, N = 10.0, 0.001, 10000
x, v = np.zeros(N+1), np.zeros(N+1)
x[0] = 0.05
for n in range(N):
    v[n+1] = v[n] - h*w*w*x[n]
    x[n+1] = x[n] + h*v[n]  # Euler explicite
energy = 0.5*(v*v + w*w*x*x)
t = h*np.arange(N+1)
exact = 0.05*np.cos(w*t)
\end{verbatim}
'''+qs(r"Tracer x et la solution exacte, puis le rapport d’énergie à l’énergie initiale.",r"Démontrer $\mathcal E_{n+1}=(1+h^2\omega_0^2)\mathcal E_n$ pour Euler explicite.",r"Remplacer la mise à jour de x par $x_{n+1}=x_n+h v_{n+1}$. Comparer la dérive et réduire h.","Expliquer pourquoi un résultat numérique oscillant n’est pas nécessairement un bon résultat physique.")+box('piege','Une croissance artificielle',"Le modèle exact conserve l’énergie. Une croissance dans cette expérience numérique signale un défaut du schéma ou du pas, et ne prouve aucune instabilité physique du ressort.")
 c.synthesis=box('loi','L’essentiel avec ses hypothèses',r"Sans dissipation, autour d’un équilibre stable linéaire : $\ddot X+\omega_0^2X=0$.\par $X=X_0\cos\omega_0t+(V_0/\omega_0)\sin\omega_0t$.\par $A=\sqrt{X_0^2+(V_0/\omega_0)^2}$ ; $T_0=2\pi/\omega_0$.\par Ressort : $\omega_0=\sqrt{k/m}$ ; LC : $\omega_0=1/\sqrt{LC}$.\par Énergie conservée : $mv^2/2+kX^2/2$ ou $Li^2/2+q^2/(2C)$.")+sub('À refaire',qs("Établir l’équation à partir des forces ou des lois de maille.","Fixer les deux constantes avec les deux conditions initiales.","Retrouver amplitude et quadrant de phase.","Établir l’ellipse de phase à partir de l’énergie."))+box('docu','Avant de rendre',r"\checkline{L’origine est l’équilibre pertinent.}\checkline{Les deux conditions initiales sont satisfaites.}\checkline{Amplitude et déplacement initial sont distingués.}\checkline{L’énergie et les limites physiques sont vérifiées.}")
 c.td_titles=['Identifier le mouvement','Fixer amplitude et phase','Lire les oscillations','Utiliser l’énergie','Passer à l’électricité','Changer l’équilibre','Exploiter des mesures','Vérifier un modèle']
 entries=[
 ('Une pulsation à identifier',1,'8 min',qs(r"Résoudre $\ddot x+400x=0$ pour $x(0)=2$ cm, $v(0)=0$. Donner période et fréquence."),r"$\omega_0=20$ rad/s ; $x=0{,}020\cos20t$ m ; $T_0=\pi/10=0{,}3142$ s ; $f_0=10/\pi=3{,}183$ Hz."),
 ('Une masse et une raideur',1,'10 min',qs(r"$m=0{,}50$ kg, $k=50$ N/m. Établir l’équation pour l’écart x à l’équilibre et calculer $T_0$. Que devient la période si la masse est multipliée par quatre ?"),r"$\ddot x+100x=0$ ; $T_0=0{,}6283$ s. Comme $T_0\propto\sqrt m$, la nouvelle période est doublée. La pulsation est divisée par deux."),
 ('Un lancement à l’équilibre',1,'10 min',qs(r"$\omega_0=5$ rad/s ; $x(0)=0$, $v(0)=0{,}20$ m/s. Donner x(t), l’amplitude et une phase dans l’écriture cosinus."),r"$x=0{,}040\sin5t$ m ; $A=4$ cm et $\varphi=-\pi/2$ dans $A\cos(5t+\varphi)$. La pente initiale est positive."),
 ('Deux conditions non nulles',2,'12 min',qs(r"$\omega_0=10$ rad/s, $x_0=3$ cm, $v_0=0{,}40$ m/s. Déterminer x(t), A et la phase."),r"$x=0{,}03\cos10t+0{,}04\sin10t$ m ; $A=0{,}05$ m ; $\varphi=\operatorname{atan2}(-0{,}04,0{,}03)=-0{,}9273$ rad. Vérifier les deux conditions en dérivant."),
 ('Le quadrant oublié',2,'12 min',qs(r"$x_0=-2$ cm et $v_0=0$ pour $\omega_0=8$ rad/s. Une copie propose $A=2$ cm et $\varphi=0$ car $\tan\varphi=0$. Corriger et expliquer."),r"La phase doit vérifier $A\cos\varphi=-2$ cm : $\varphi=\pi$ à $2\pi$ près. La tangente seule ne distingue pas 0 de $\pi$. $x=-0{,}02\cos8t$ m."),
 ('Retrouver une vitesse initiale',2,'12 min',qs(r"$x=0{,}06\cos(4t+\pi/3)$ en SI. Calculer $x(0),v(0),v_{\max}$ et $a(0)$."),r"$x(0)=0{,}030$ m ; $v(0)=-0{,}24\sin(\pi/3)=-0{,}2078$ m/s ; $v_{\max}=0{,}24$ m/s ; $a(0)=-16\times0{,}03=-0{,}48$ m/s$^2$."),
 ('Un enregistrement décentré',1,'10 min',qs(r"Un signal oscille entre 3 et 11 cm et deux maxima successifs sont séparés de 0,80 s. Donner équilibre, amplitude, période, fréquence et pulsation."),r"Équilibre 7 cm, amplitude 4 cm, période 0,80 s, fréquence 1,25 Hz et pulsation $2{,}5\pi=7{,}854$ rad/s. L’amplitude n’est ni 11 cm ni 8 cm."),
 ('Le premier passage',2,'15 min',qs(r"Une masse est libérée sans vitesse à $x=A>0$. Quand passe-t-elle pour la première fois à x = A/2 ? Donner le signe et la valeur de la vitesse à cet instant."),r"$x=A\cos\omega_0t$ ; premier passage à $\omega_0t=\pi/3$, donc $t=T_0/6$. $v=-A\omega_0\sin(\pi/3)=-\sqrt3A\omega_0/2$."),
 ('Un déphasage à lire',2,'12 min',qs(r"Pour $x=A\cos\omega_0t$ et $v=-A\omega_0\sin\omega_0t$, écrire v sous forme cosinus. Donner sa phase relativement à x et expliquer le signe."),r"$v=A\omega_0\cos(\omega_0t+\pi/2)$. La phase de v dépasse celle de x de $\pi/2$. À t = 0 la vitesse est nulle et devient négative, ce qui est cohérent avec le rappel."),
 ('Une énergie à deux instants',1,'12 min',qs(r"$m=0{,}2$ kg, $k=20$ N/m, $A=5$ cm. Calculer l’énergie totale puis les deux énergies à x = 3 cm."),r"$\mathcal E=kA^2/2=0{,}025$ J ; à 3 cm, $\mathcal E_p=0{,}009$ J et $\mathcal E_c=0{,}016$ J. La vitesse a un module de 0,40 m/s."),
 ('Retrouver une amplitude',2,'12 min',qs(r"À un instant, $x=4$ cm et $v=-0{,}30$ m/s, avec $\omega_0=10$ rad/s. Donner A ; préciser si la masse s’approche de l’équilibre."),r"$A=\sqrt{x^2+(v/\omega_0)^2}=5$ cm. Puisque x > 0 et v < 0, la masse se rapproche de l’équilibre. L’énergie seule ne détermine pas ce sens."),
 ('Une ellipse de phase',2,'15 min',qs(r"Un portrait possède les demi-axes $A=2$ cm et $v_{\max}=0{,}50$ m/s. Déterminer $\omega_0$, T et k pour m = 0,10 kg. Indiquer le sens de parcours."),r"$\omega_0=v_{\max}/A=25$ rad/s ; $T=0{,}2513$ s ; $k=m\omega_0^2=62{,}5$ N/m. Dans le plan (x,v), le parcours est horaire car l’accélération est négative au point (A,0)."),
 ('Un circuit LC',1,'12 min',qs(r"$L=10$ mH, $C=10\ \mathrm{\mu F}$, $u_C(0)=5$ V et $i(0)=0$ avec $i=C\dot u_C$. Donner u, i et la période."),r"$\omega_0=3162{,}3$ rad/s ; $u=5\cos\omega_0t$ V ; $i=-0{,}1581\sin\omega_0t$ A ; $T=1{,}987$ ms. Le courant initial est nul mais sa pente est négative."),
 ('Une intensité initiale',2,'15 min',qs(r"LC idéal : $L=0{,}10$ H, $C=1\ \mathrm{\mu F}$, $u_C(0)=0$, $i(0)=10$ mA dans $i=C\dot u_C$. Donner l’amplitude de tension et l’énergie."),r"$u=(I_0/(C\omega_0))\sin\omega_0t$. Son amplitude vaut $I_0\sqrt{L/C}=3{,}162$ V. L’énergie initiale est $LI_0^2/2=5\ \mathrm{\mu J}$."),
 ('Une tension nulle, une réserve pleine',2,'12 min',qs(r"Une capacité de 2 $\mathrm{\mu F}$ initialement à 10 V oscille avec L = 50 mH. Calculer l’énergie et le courant maximal. Où est l’énergie lorsque uC = 0 ?"),r"$\mathcal E=100\ \mathrm{\mu J}$ ; $I_{\max}=U_0\sqrt{C/L}=63{,}25$ mA. À uC = 0, toute l’énergie est magnétique dans la bobine idéale, pas dissipée."),
 ('Une force constante',2,'15 min',qs(r"$m=0{,}20$ kg, $k=20$ N/m, $F_0=1$ N est appliquée à t = 0 ; $x(0)=v(0)=0$. Déterminer l’équilibre et x(t), puis le maximum de x."),r"$x_e=F_0/k=0{,}05$ m, $\omega_0=10$ rad/s ; $x=0{,}05(1-\cos10t)$ m. Le maximum vaut 0,10 m, atteint à $t=\pi/10$ s. Le système oscille autour de 5 cm."),
 ('Un ressort vertical',2,'18 min',qs(r"m = 0,10 kg, k = 10 N/m, g = 10 m/s$^2$. L’allongement z est positif vers le bas. On lâche la masse au ressort non allongé. Donner z(t) et sa plage de variation."),r"$z_e=mg/k=0{,}10$ m ; $\omega_0=10$ rad/s. Avec z(0) = 0 et v(0) = 0, $z=0{,}10(1-\cos10t)$ m, entre 0 et 0,20 m. La pesanteur déplace le centre sans modifier la pulsation."),
 ('LC sous un échelon',2,'18 min',qs(r"Un LC série idéal reçoit E constant à partir de t = 0. La capacité est déchargée et le courant nul. Établir uC(t). Calculer le maximum de tension et l’énergie stockée à cet instant."),r"$LC\ddot u+u=E$ ; $u=E(1-\cos\omega_0t)$. Le maximum 2E est atteint à $\pi/\omega_0$ avec i = 0. L’énergie est alors $C(2E)^2/2=2CE^2$, égale à l’énergie fournie $E\Delta q=2CE^2$."),
 ('Raideur et incertitude',2,'15 min',qs(r"m = 0,200 kg, u(m) = 0,002 kg, T = 0,630 s, u(T) = 0,005 s, indépendants. Déterminer k et u(k)."),r"$k=4\pi^2m/T^2=19{,}89$ N/m. L’incertitude relative vaut $\sqrt{0{,}01^2+(2\times0{,}005/0{,}630)^2}=0{,}01876$, donc u(k) = 0,373 N/m. On peut présenter k = 19,9 N/m, u(k) = 0,4 N/m."),
 ('Dix périodes',1,'12 min',qs(r"Dix périodes occupent 6,28 s. Chaque date extrême a une incertitude-type 0,02 s, indépendante de l’autre. Donner T et u(T)."),r"T = 0,628 s ; $u(T)=\sqrt{0{,}02^2+0{,}02^2}/10=0{,}00283$ s. Mesurer plusieurs cycles réduit l’incertitude sur une période si le comptage est correct."),
 ('Deux ressorts',3,'20 min',qs(r"Une masse est attachée entre deux ressorts horizontaux de raideurs k1 et k2, chacun fixé à un mur. Démontrer la raideur effective pour un déplacement depuis l’équilibre et donner la période."),r"Un déplacement x allonge un ressort et raccourcit l’autre ; les variations des deux forces de rappel s’ajoutent : $F_x=-(k_1+k_2)x$. Ainsi $T=2\pi\sqrt{m/(k_1+k_2)}$. Les précontraintes fixent l’équilibre, pas ce coefficient linéaire."),
 ('Un pendule dans le modèle linéaire',3,'20 min',qs(r"On admet $\ddot\theta+(g/\ell)\sin\theta=0$. À petits angles, établir la période. Pour $\ell=1$ m et g = 9,81 m/s$^2$, calculer sa valeur et discuter l’influence de la masse."),r"$\sin\theta\simeq\theta$ donne $\omega_0=\sqrt{g/\ell}$ et $T=2\pi\sqrt{\ell/g}=2{,}006$ s. La masse n’apparaît pas ; l’approximation exige des angles en radians suffisamment petits. L’équation non linéaire ne prédit plus un isochronisme exact."),
 ('Une énergie numérique qui augmente',3,'20 min',qs(r"Euler explicite : $x_{n+1}=x_n+hv_n$ et $v_{n+1}=v_n-h\omega_0^2x_n$. Établir le facteur de croissance de $v^2+\omega_0^2x^2$. Pour h = 0,01 s et $\omega_0=10$ rad/s, calculer le facteur après 100 pas."),r"Les termes croisés s’annulent : $v_{n+1}^2+\omega_0^2x_{n+1}^2=(1+h^2\omega_0^2)(v_n^2+\omega_0^2x_n^2)$. Le facteur est $1{,}01^{100}=2{,}705$. Cette croissance est numérique et contredit l’énergie exacte constante."),
 ('Un état après un choc',3,'25 min',qs(r"Une masse m à l’équilibre reçoit une impulsion de quantité de mouvement J, puis oscille librement sur k. On admet $m[v(0^+)-v(0^-)]=J$ et x continue. Déterminer x(t), l’amplitude et l’énergie injectée."),r"Avant le choc x = 0 et v = 0. Après, x0 = 0 et v0 = J/m. Donc $x=J\sin(\omega_0t)/(m\omega_0)$ ; $A=|J|/\sqrt{mk}$ ; $\mathcal E=J^2/(2m)$. L’impulsion est un modèle d’action très brève ; la force pendant le choc n’est pas décrite par le seul ressort.")]
 for e in entries:c.e(*e)
 c.d('Une impulsion au bon moment',r"Un oscillateur de masse m, de pulsation $\omega_0$, possède une amplitude A. À un instant où x = 0 et v = $+\omega_0A$, une impulsion J s’applique dans le sens positif."+qs(r"Déterminer la nouvelle amplitude et la variation d’énergie.",r"Comparer avec la même impulsion appliquée à x = A et v = 0.",r"Pour m = 0,20 kg, $\omega_0=10$ rad/s, A = 5 cm et J = 0,02 kg·m/s, effectuer les deux calculs.","À quel moment une impulsion donnée augmente-t-elle le plus l’énergie ? Que change son sens ?"),"1. La position reste continue ; la vitesse gagne J/m. 2. Calculer l’énergie immédiatement avant et après. 3. Le terme croisé Jv explique l’effet de phase.",r'''La variation d’énergie cinétique au choc vaut $\Delta\mathcal E=Jv^-+J^2/(2m)$. Au passage positif par l’équilibre, $v^-=\omega_0A$ ; l’amplitude devient $A'=|A+J/(m\omega_0)|$.
À la position extrême, $v^-=0$ ; $\Delta\mathcal E=J^2/(2m)$ et $A'=\sqrt{A^2+[J/(m\omega_0)]^2}$.
Numériquement, $J/(m\omega_0)=0{,}010$ m. Au passage par l’équilibre : $A'=6$ cm, $\Delta\mathcal E=0{,}011$ J. À l’extrême : $A'=\sqrt{0{,}0026}=5{,}099$ cm, $\Delta\mathcal E=0{,}001$ J.
L’impulsion positive augmente au mieux l’énergie lorsque la vitesse est maximale et positive. Une impulsion opposée peut au contraire diminuer l’énergie si le terme croisé négatif dépasse $J^2/(2m)$. La phase d’application est donc déterminante.
''')
 c.d('Couper une alimentation au bon instant',r"Un LC série idéal, initialement déchargé et sans courant, reçoit une source E. À $t=t_s$, la source est remplacée par un fil sans rompre la boucle."+qs(r"Écrire l’état juste avant puis juste après la commutation.",r"Déterminer la nouvelle amplitude de tension en régime libre.",r"Exprimer l’énergie restante en fonction de $t_s$ et rechercher les dates qui la maximisent ou l’annulent.",r"Calculer pour L = 10 mH, C = 10 $\mathrm{\mu F}$, E = 5 V, $t_s=T_0/4$."),"1. Utiliser la réponse à l’échelon LC. 2. uC et iL restent continus. 3. L’amplitude libre dépend des deux réserves, pas seulement de la tension à la coupure.",r'''Avant la coupure, $u_s=E(1-\cos\omega_0t_s)$ et $i_s=CE\omega_0\sin\omega_0t_s$. Après remplacement de la source, ces deux valeurs sont conservées. Pour $t'=t-t_s$,
\[u=u_s\cos\omega_0t'+\frac{i_s}{C\omega_0}\sin\omega_0t'.\]
L’amplitude vaut $A_u=E\sqrt{(1-\cos\theta)^2+\sin^2\theta}=2E|\sin(\theta/2)|$, avec $\theta=\omega_0t_s$. L’énergie est $\mathcal E=CA_u^2/2=CE^2(1-\cos\theta)$.
Elle est maximale pour $t_s=(n+1/2)T_0$ et nulle pour $t_s=nT_0$. Au quart de période, $u_s=E=5$ V, $i_s=CE\omega_0=0{,}1581$ A ; $A_u=5\sqrt2=7{,}071$ V et $\mathcal E=250\ \mathrm{\mu J}$. Le courant initial non nul explique que l’amplitude finale dépasse la tension à la coupure.
''')
 c.d('Peut-on identifier toute la mécanique ?',r"On observe x(t) sans mesurer les forces. L’ajustement donne une pulsation $\omega_0$ et une amplitude A. La masse mobile est inconnue."+qs(r"Peut-on déterminer séparément m et k ? Identifier la combinaison observable.",r"On ajoute une masse connue $\Delta m$ ; la période passe de $T_1$ à $T_2$. Établir m et k.",r"Calculer pour $\Delta m=0{,}10$ kg, $T_1=0{,}60$ s et $T_2=0{,}80$ s.","Proposer un contrôle avec une troisième masse et expliquer le rôle d’un éventuel décalage d’équilibre."),"1. La période fixe k/m. 2. Soustraire les deux relations de T². 3. L’équilibre modifie le centre ; l’ajout de masse modifie l’inertie.",r'''Une courbe seule donne $k/m=\omega_0^2$, mais pas k et m séparément : multiplier les deux par la même constante laisse x(t) inchangé à conditions initiales identiques.
Avec la masse ajoutée, $T_1^2=4\pi^2m/k$ et $T_2^2=4\pi^2(m+\Delta m)/k$. Donc
\[k=\frac{4\pi^2\Delta m}{T_2^2-T_1^2},\qquad m=\frac{\Delta mT_1^2}{T_2^2-T_1^2}.\]
On trouve $m=0{,}12857$ kg et $k=14{,}099$ N/m. Une troisième masse doit respecter la même droite $T^2(m_{\rm ajouté})$. Un ressort vertical peut changer d’allongement d’équilibre lors de l’ajout, sans changer la forme de cette relation si le domaine reste linéaire. Les incertitudes sur deux périodes voisines peuvent fortement affecter la différence de leurs carrés.
''')
 c.dm_title='Deux expériences, une même équation'
 c.dm=r"Un oscillateur masse-ressort a m = 0,20 kg et k = 20 N/m. Un LC idéal a L = 100 mH. On veut la même pulsation propre."+qs(r"Calculer $\omega_0$ et la capacité nécessaire. \textbf{3 points}",r"Pour $x_0=3$ cm, $v_0=0{,}40$ m/s, donner x(t), amplitude et phase. \textbf{5 points}",r"Établir l’énergie mécanique et son partage à t = 0. \textbf{3 points}",r"Dans le LC, $u_0=2$ V et $i_0=0$. Donner u(t), i(t) et l’énergie totale. \textbf{4 points}",r"Tracer qualitativement les deux portraits réduits et proposer un protocole qui teste l’isochronisme. \textbf{5 points}")
 c.dm_sol=sub('1 et 2 / 8 points',r"$\omega_0=10$ rad/s ; $C=1/(L\omega_0^2)=0{,}10$ F (3). $x=0{,}03\cos10t+0{,}04\sin10t$ m ; A = 5 cm ; $\varphi=-0{,}9273$ rad (coefficients 2 ; amplitude 1 ; phase et vérification 2). La grande capacité choisie sert ici à illustrer l’analogie, pas à imposer un montage usuel.")+sub('3 / 3 points',r"$\mathcal E_p(0)=9$ mJ ; $\mathcal E_c(0)=16$ mJ ; $\mathcal E=25$ mJ. Sa dérivée s’annule par l’équation de mouvement.")+sub('4 / 4 points',r"$u=2\cos10t$ V ; $i=C\dot u=-2\sin10t$ A ; $\mathcal E=Cu_0^2/2=0{,}20$ J. Les unités et le signe de i doivent être justifiés.")+sub('5 / 5 points',r"En variables x/A et v/($\omega_0$A), et de même u/Au et i/($C\omega_0A_u$), le portrait est circulaire et parcouru dans le sens horaire (2). Mesurer plusieurs périodes pour plusieurs amplitudes, comparer avec les incertitudes, suivre les pertes et conserver les autres paramètres (3).")
 c.ds_title='Osciller et échanger de l’énergie'
 c.ds=[sub('A / Masse-ressort / 8 points',r"m = 0,25 kg, k = 25 N/m ; x mesure l’écart à l’équilibre. On donne $x_0=-4$ cm et $v_0=0{,}30$ m/s.")+qs(r"Établir l’équation et calculer pulsation et période. \textbf{2 points}",r"Résoudre puis déterminer amplitude et phase en justifiant le quadrant. \textbf{3 points}",r"Calculer l’énergie totale et le module maximal de la vitesse. \textbf{2 points}",r"Le mobile se rapproche-t-il initialement de l’équilibre ? \textbf{1 point}")+sub('B / Circuit LC / 7 points',r"L = 20 mH, C = 5 $\mathrm{\mu F}$ ; $u_C(0)=4$ V et i(0) = 0, avec $i=C\dot u_C$.")+qs(r"Établir l’équation et donner uC(t). \textbf{3 points}",r"Donner le courant, son module maximal et l’énergie totale. \textbf{3 points}",r"Où est l’énergie au premier instant où uC = 0 ? \textbf{1 point}"),sub('C / Déplacement de l’équilibre / 5 points',r"Une masse m est sur un ressort k. À t = 0, une force constante F0 est appliquée ; x(0) = 0 et v(0) = 0.")+qs(r"Déterminer le nouvel équilibre et résoudre le mouvement. \textbf{3 points}",r"Calculer le déplacement maximal et montrer que le travail de F0 entre le départ et ce maximum égale l’énergie stockée dans le ressort. \textbf{2 points}")]
 c.ds_sol=[sub('A / 8 points',r"$m\ddot x=-kx$, $\omega_0=10$ rad/s, T = 0,6283 s (2). $x=-0{,}04\cos10t+0{,}03\sin10t$ m ; A = 0,05 m et $\varphi=\operatorname{atan2}(-0{,}03,-0{,}04)=-2{,}4981$ rad (3). $\mathcal E=kA^2/2=31{,}25$ mJ ; $v_{\max}=0{,}50$ m/s (2). x < 0 et v > 0 : il s’approche de l’équilibre (1).")+sub('B / 7 points',r"$\ddot u+u/(LC)=0$ ; $\omega_0=3162{,}3$ rad/s ; $u=4\cos\omega_0t$ V (3). $i=-C\omega_0\,4\sin\omega_0t$ ; $I_{\max}=63{,}25$ mA ; $\mathcal E=40\ \mathrm{\mu J}$ (3). Lorsque u = 0, l’énergie est entièrement magnétique (1)."),sub('C / 5 points',r"$x_e=F_0/k$ ; pour X = x - xe, $\ddot X+(k/m)X=0$. Ainsi $x=(F_0/k)(1-\cos\omega_0t)$ (3). $x_{\max}=2F_0/k$, atteint à $\pi/\omega_0$. Le travail vaut $F_0x_{\max}=2F_0^2/k$, égal à $kx_{\max}^2/2$ ; la vitesse est alors nulle (2).")+box('methode','Un signe doit avoir un sens',"Le courant négatif au début de la décharge n’est pas une anomalie. Une phase dans un autre intervalle est acceptable si les conditions initiales sont satisfaites à 2π près.")]
 c.hints="E05 : déterminer cosφ et sinφ, pas seulement tanφ. E08 : prendre le premier angle positif. E12 : convertir les centimètres avant le rapport des axes. E18 : translater la tension de E. E24 : l’impulsion fixe la vitesse après le choc."
 c.eval_hints="Dans le DM, conserver les unités SI même si la capacité calculée est grande. Dans le DS, une amplitude positive impose un choix cohérent de phase ; vérifier la vitesse initiale par dérivation."
 c.source('DS réel / Un chariot oscillant','https://cahier-de-prepa.fr/mp*-condorcet/download?id=98&v=66f32','Archive de révision SUP, site MP* Condorcet ; DS5 du 7 janvier 2023 ; problème I, partie I, questions 1 à 5, page PDF 1.',"Prévoir 30 minutes. Garder le graphe original : il donne une position absolue x, et non directement l’écart à l’équilibre. Mesurer plusieurs périodes.",r"$x_e=\ell_0$. La lecture donne environ $\ell_0=10$ cm, A = 5 cm, x(0) = 15 cm et v(0) = 0 ; T est voisin de 0,71 à 0,72 s. Avec m = 0,10 kg, $k=4\pi^2m/T^2\simeq7{,}7$ à 7,8 N/m, cohérent avec 7,78 N/m indiqué ensuite. $x=\ell_0+A\cos\omega_0t$. Pour un lancement à l’équilibre, $x=\ell_0+(v_0/\omega_0)\sin\omega_0t$. L’exigence de longueur non négative impose $|v_0|\leq\omega_0\ell_0\simeq0{,}88$ m/s.")
 c.source('Concours réel / Isochronisme','https://www.concours-commun-inp.fr/_resource/annales%20%C3%A9crits/2024/MP/2024_MP2PC.pdf?download=true','CCINP 2024, filière MP, Physique-chimie ; partie III.1, Q19 a à c, pages imprimées 11/19 et 12/19 (PDF 11 et 12).',r"Prévoir 20 minutes. Pour rester dans les outils de ce chapitre, admettre le résultat de Q18 : $J_F\ddot\theta=-m_jg\Delta\sin\theta$. Le théorème du moment cinétique nécessaire à sa démonstration sera étudié ultérieurement. Traiter ensuite les trois points de Q19.",r"À petits angles, $\sin\theta\simeq\theta$, d’où $\omega_{os}=\sqrt{m_jg\Delta/J_F}$. L’isochronisme signifie que la période ne dépend pas de l’amplitude dans ce modèle. La phase étudiée va d’un extrême à l’autre : sa durée vaut une demi-période, $\tau_{os}=\pi\sqrt{J_F/(m_jg\Delta)}$. Utiliser une période entière doublerait à tort la durée. Le reste du sujet demande d’autres chapitres.")
 c.next="Le chapitre 05 réintroduit les pertes : l’énergie décroît et les racines de l’équation déterminent un retour oscillant, critique ou apériodique."
 for n,a,b,tol in [('E01-T',2*pi/20,.3141592653589793,1e-12),('E04-A',sqrt(.03**2+.04**2),.05,1e-12),('E04-phase',atan2(-.04,.03),-.9272952180016123,1e-12),('E06-v',-.24*sin(pi/3),-.20784609690826525,1e-12),('E10-E',.5*20*.05**2,.025,1e-12),('E12-k',.1*25**2,62.5,1e-12),('E13-I',5*sqrt(1e-5/.01),.15811388300841897,1e-12),('E14-U',.01*sqrt(.1/1e-6),3.1622776601683795,1e-12),('E15-E',.5*2e-6*100,1e-4,1e-12),('E19-k',4*pi*pi*.2/.63**2,19.89338251668301,1e-8),('E20-uT',sqrt(2)*.02/10,.00282842712474619,1e-12),('E22-T',2*pi/sqrt(9.81),2.0060666807106475,1e-12),('E23-dérive',1.01**100,2.7048138294215285,1e-12),('D1-gain',.02*.5+.02**2/(2*.2),.011,1e-12),('D2-E',1e-5*25,.00025,1e-12),('D3-m',.1*.6**2/(.8**2-.6**2),.12857142857142853,1e-12),('DM-C',1/(.1*100),.1,1e-12),('DS-phase',atan2(-.03,-.04),-2.498091544796509,1e-12),('DS-I',4*sqrt(5e-6/.02),.0632455532033676,1e-12)]:c.check(n,a,b,tol)
 return c
